$user=currentUser();if(!$user){http_response_code(401);echo json_encode(['success'=>false,'error'=>'Bạn cần đăng nhập.']);exit;}$in=jsonRequest();$id=(int)($in['itinerary_id']??0);$db=getDB();$s=$db->prepare('SELECT i.*,d.latitude AS dlat,d.longitude AS dlng FROM itinerary_items i LEFT JOIN destinations d ON d.id=i.destination_id JOIN itineraries t ON t.id=i.itinerary_id WHERE i.itinerary_id=? AND t.user_id=? ORDER BY i.day_number,i.sort_order');$s->execute([$id,$user['id']]);$items=$s->fetchAll();if(!$items){echo json_encode(['success'=>false,'error'=>'Lịch trình không có item.']);exit;}
function osrmMatrix(array $points): ?array{$coords=[];foreach($points as $p)$coords[]=$p['dlng'].','.$p['dlat'];if(count($coords)<2)return null;$ch=curl_init('https://router.project-osrm.org/table/v1/driving/'.implode(';',$coords).'?annotations=duration');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>5]);$raw=curl_exec($ch);curl_close($ch);$data=json_decode((string)$raw,true);return ($data['code']??'')==='Ok'&&is_array($data['durations']??null)?$data['durations']:null;}
$groups=[];foreach($items as $item){$groups[(int)$item['day_number']][]=$item;}$ordered=[];foreach($groups as $day=>$group){$fixed=[];$movable=[];foreach($group as $item){if((int)$item['is_locked']||$item['dlat']===null||$item['dlng']===null)$fixed[]=$item;else$movable[]=$item;}$matrixPoints=array_values(array_filter($group,fn($x)=>$x['dlat']!==null&&$x['dlng']!==null));$matrix=osrmMatrix($matrixPoints);$matrixIndex=[];foreach($matrixPoints as $idx=>$point)$matrixIndex[(int)$point['id']]=$idx;$route=[];$current=$fixed[0]??null;while($movable){$best=0;$bestDist=INF;if($current){foreach($movable as $k=>$candidate){$dist=null;if($matrix&&isset($matrixIndex[(int)$current['id']],$matrixIndex[(int)$candidate['id']]))$dist=(float)($matrix[$matrixIndex[(int)$current['id']]][$matrixIndex[(int)$candidate['id']]]??INF);if($dist===null)$dist=geoHaversineMeters((float)$current['dlat'],(float)$current['dlng'],(float)$candidate['dlat'],(float)$candidate['dlng']);if($dist<$bestDist){$bestDist=$dist;$best=$k;}}}$route[]=$movable[$best];$current=$movable[$best];array_splice($movable,$best,1);}$merged=array_merge($fixed,$route);foreach($merged as $index=>&$row)$row['sort_order']=$index;unset($row);$ordered=array_merge($ordered,$merged);}
echo json_encode(['success'=>true,'items'=>$ordered,'warning'=>'Đã tối ưu tuyến theo khoảng cách GPS; hãy xác nhận và lưu.'],JSON_UNESCAPED_UNICODE);
